  MINIMUM_REQUIREMENTS:
    "http://ihris.org/fhir/StructureDefinition/minimum-requirements",
  ADDITIONAL_REQUIREMENTS:
    "http://ihris.org/fhir/StructureDefinition/additional-requirements",
