      // ── processQuestionnaire bindings ───────────────────────────────
      url: "http://ihris.org/fhir/Questionnaire/vacancy-advertisement",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/vacancy-advertisement-profile",

      loading: false,
      saving: false,
      formValid: true,
      hiringClosed: false,
      formSubmitted: false,

      // ── Date picker menus ───────────────────────────────────────────
      startDateMenu: false,
      endDateMenu: false,
      employmentEndMenu: false,

      // ── Form model ──────────────────────────────────────────────────
      form: {
        name: "",
        description: "",
        position: {
          reference: null,
          display: "",
          facility: "",
          department: "",
        },
        startDate: null,
        endDate: null,
        maximumPractitioners: null,
        employmentCategory: null,
        employmentEnd: null,
      },

      // Rich position details shown after a position is selected
      positionDetails: null,
      positionResource: null,

      // ── Extend deadline dialog ──────────────────────────────────────
      extendDialog: false,
      extendDateMenu: false,
      extendDate: null,
      extendError: "",

      // ── Position picker ─────────────────────────────────────────────
      positionDialog: false,
      positionItems: [],
      positionTotal: 0,
      loadingPositions: false,
      positionOptions: { page: 1, itemsPerPage: 10, sortBy: [], sortDesc: [] },
      posFilter: { designation: "", department: null },
      posDebounce: null,

      positionHeaders: [
        { text: "Designation", value: "designation", sortable: false },
        { text: "Department", value: "department", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        { text: "Grade", value: "grade", sortable: false },
        { text: "Vacant / Max", value: "vacant", sortable: false, width: 130 },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 100,
        },
      ],

      // ── Filter treeview (shared between picker and supervisor dialogs)
      posFilterTreeOpen: false,
      filterTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {},
        loading: false,
        displayValue: "",
      },

      // ── ValueSet options ────────────────────────────────────────────
      departmentOptions: [],
      employmentCategoryOptions: [],

      // ── Validation rules ────────────────────────────────────────────
      rules: {
        required: (v) => !!v || "This field is required",
        positiveInt: (v) =>
          (Number.isInteger(+v) && +v > 0) ||
          "Must be a whole number greater than 0",
      },
    };
  },

  computed: {
    isEdit() {
      return !!this.queries?.advert;
    },

    positionOverviewFields() {
      if (!this.positionDetails) return [];
      return [
        { label: "Designation",        value: this.positionDetails.designation || "—" },
        { label: "Salary Grade",        value: this.positionDetails.grade || "—" },
        { label: "Department",          value: this.positionDetails.department || "—" },
        { label: "Facility",            value: this.positionDetails.facility || "—" },
        { label: "District",            value: this.positionDetails.district || "—" },
        { label: "Available Vacancies", value: this.positionDetails.maxPosts, highlight: true },
      ];
    },

    hasSpecs() {
      const SPEC = "http://ihris.org/fhir/StructureDefinition/position-specification";
      return !!(this.positionResource &&
        (this.positionResource.extension || []).some((e) => e.url === SPEC));
    },

    showEmploymentEnd() {
      return (
        this.form.employmentCategory &&
        this.form.employmentCategory.code !== "position_category|permanent"
      );
    },

    // Earliest allowed end date = start date + 30 days (statutory minimum)
    minEndDate() {
      if (!this.form.startDate) return null;
      const d = new Date(this.form.startDate);
      d.setDate(d.getDate() + 30);
      return d.toISOString().split("T")[0];
    },

    // Earliest allowed extension date = current end date + 1 day
    minExtendDate() {
      if (!this.form.endDate) return null;
      const d = new Date(this.form.endDate);
      d.setDate(d.getDate() + 1);
      return d.toISOString().split("T")[0];
    },

    advertisementDays() {
      if (!this.form.startDate || !this.form.endDate) return 0;
      const diff = new Date(this.form.endDate) - new Date(this.form.startDate);
      return Math.floor(diff / 86400000);
    },

    durationHint() {
      if (!this.advertisementDays) return "";
      return `${this.advertisementDays} day${
        this.advertisementDays !== 1 ? "s" : ""
      }`;
    },

    extendDurationDays() {
      if (!this.form.endDate || !this.extendDate) return 0;
      return Math.floor(
        (new Date(this.extendDate) - new Date(this.form.endDate)) / 86400000,
      );
    },

    // Closing date must be at least 30 days after the open date
    closingDateRule() {
      return (v) => {
        if (!v || !this.form.startDate) return true;
        const days = Math.floor(
          (new Date(v) - new Date(this.form.startDate)) / 86400000,
        );
        return (
          days >= 30 ||
          "Closing date must be at least 30 days after the open date (statutory minimum)"
        );
      };
    },

    canSubmit() {
      return (
        !this.hiringClosed &&
        !!this.form.position.reference &&
        !!this.form.name.trim() &&
        !!this.form.startDate &&
        !!this.form.endDate &&
        !!this.form.maximumPractitioners &&
        Number.isInteger(+this.form.maximumPractitioners) &&
        +this.form.maximumPractitioners > 0
      );
    },

    // Maximum practitioners must not exceed available vacancies on the position
    maxPractitionersRule() {
      return (v) => {
        if (!this.positionDetails?.maxPosts) return true;
        return (
          +v <= this.positionDetails.maxPosts ||
          `Cannot exceed ${this.positionDetails.maxPosts} (available vacancies on this position)`
        );
      };
    },
  },

  watch: {
    "filterTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.filterTree.displayValue = id
        ? this.filterTree.treeLookup[id]?.name || id
        : "";
      this.fetchPositions();
    },
    positionOptions: {
      handler() {
        if (this.positionDialog) this.fetchPositions();
      },
      deep: true,
    },
  },

  async mounted() {
    this.loading = true;
    await Promise.all([this.loadValueSets(), this.loadFilterTree()]);
    if (this.isEdit) await this.loadExistingAdvert();
    this.loading = false;
  },

  methods: {
    goToLanding() {
      this.$router.push({
        path: "/custom/index",
        query: { path: "/lesotho/components/recruitment" },
      });
    },

    // ── ValueSets ──────────────────────────────────────────────────────
    async loadValueSets() {
      const [dept, empCat] = await Promise.all([
        this.$fhirutils.expand(VS.DEPARTMENT),
        this.$fhirutils.expand(VS.EMP_CAT),
      ]);
      this.departmentOptions = this.parseExpansion(dept);
      this.employmentCategoryOptions = this.parseExpansion(empCat);
    },

    parseExpansion(vs) {
      return (vs || []).map((c) => ({
        system: c.system,
        code: c.code,
        display: c.display,
      }));
    },

    // ── Load existing advertisement for edit mode ──────────────────────
    async loadExistingAdvert() {
      try {
        const res = await fetch(`/fhir/Basic/${this.queries.advert}`);
        const data = await res.json();
        this.fhirId = this.queries.advert;

        this.form.name = this.getExt(data, EXT.ADV_NAME, "valueString") || "";
        this.form.description =
          this.getExt(data, EXT.ADV_DESCRIPTION, "valueString") || "";
        this.form.startDate =
          this.getExt(data, EXT.ADV_START, "valueDate") || null;
        this.form.endDate = this.getExt(data, EXT.ADV_END, "valueDate") || null;
        this.form.maximumPractitioners =
          this.getExt(data, EXT.ADV_MAX, "valueInteger") || null;

        const posRef = this.getExt(data, EXT.ADV_POSITION, "valueReference");
        if (posRef?.reference) {
          this.form.position.reference = posRef.reference.split("/")[1];
          this.form.position.display = posRef.display || "";
          await this.enrichPositionDetails(posRef.reference);
        }

        const empCat = this.getExt(data, EXT.EMP_CAT, "valueCoding");
        if (empCat) this.form.employmentCategory = empCat;

        const empEnd = this.getExt(data, EXT.EMP_END, "valueDate");
        if (empEnd) this.form.employmentEnd = empEnd;

        const hiringStatus = this.getExt(data, EXT.HIRING_STATUS, "valueCoding");
        this.hiringClosed = hiringStatus?.code === "closed";
      } catch (err) {
        console.error("loadExistingAdvert error", err);
      }
    },

    // ── Position picker ────────────────────────────────────────────────
    openPositionDialog() {
      if (this.hiringClosed) return;
      this.positionDialog = true;
      this.fetchPositions();
    },

    debouncedFetchPositions() {
      clearTimeout(this.posDebounce);
      this.posDebounce = setTimeout(() => {
        this.positionOptions.page = 1;
        this.fetchPositions();
      }, 350);
    },

    async fetchPositions() {
      this.loadingPositions = true;
      try {
        const params = new URLSearchParams({
          page: this.positionOptions.page,
          count: this.positionOptions.itemsPerPage,
          checkAdvert: "true", // tells the backend to include activeAdvert metadata
        });
        if (this.posFilter.designation)
          params.set("designation", this.posFilter.designation);
        if (this.posFilter.department)
          params.set("department", this.posFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/report?${params}`);
        const data = await res.json();

        this.positionTotal = data.total || 0;
        this.positionItems = data.positions || [];
      } catch (err) {
        console.error("fetchPositions error", err);
      } finally {
        this.loadingPositions = false;
      }
    },

    // A position is selectable only if:
    //  - it has at least one vacant post
    //  - its status is active
    //  - it has no currently-active advertisement (date overlap check done server-side)
    canSelectPosition(item) {
      return (
        item.vacant > 0 && item.statusCode === "active" && !item.activeAdvert
      );
    },

    positionRowClass(item) {
      if (!this.canSelectPosition(item)) return "ap-row-full";
      return "";
    },

    selectionTooltip(item) {
      if (item.vacant <= 0) return "No vacant posts available";
      if (item.activeAdvert)
        return `Already advertised (active until ${this.formatDate(
          item.activeAdvert.endDate,
        )})`;
      if (item.statusCode !== "active") return "Position is not active";
      return "Select this position";
    },

    async selectPosition(item) {
      this.form.position = {
        reference: item.reference.split("/")[1],
        display: item.designation || item.display,
        facility: item.facility || "",
        department: item.department || "",
      };
      this.positionDialog = false;

      // Reset max practitioners to the available vacancies
      this.form.maximumPractitioners = item.vacant;

      // Immediately show basic info from the picker row, then enrich
      this.positionDetails = {
        designation: item.designation || "",
        grade: item.grade || "",
        department: item.department || "",
        facility: item.facility || "",
        district: item.district || "",
        maxPosts: item.vacant,
        posDescription: "",
        minimumRequirements: "",
        additionalRequirements: "",
      };

      // Fetch full position FHIR resource to resolve designation name,
      // grade name, facility name and district chain
      await this.enrichPositionDetails(item.reference, item);
    },

    clearPosition() {
      this.form.position = {
        reference: null,
        display: "",
        facility: "",
        department: "",
      };
      this.positionDetails = null;
      this.positionResource = null;
      this.form.maximumPractitioners = null;
    },

    // Fetches the full position Basic resource and chains secondary fetches to
    // resolve designation name, salary grade name, facility name and district.
    async enrichPositionDetails(positionReference, pickerItem = null) {
      try {
        const posId = positionReference.split("/")[1];
        const posRes = await fetch(`/fhir/Basic/${posId}`);
        const pos = await posRes.json();

        const details = {
          designation: pickerItem?.designation || "",
          grade: pickerItem?.grade || "",
          department: pickerItem?.department || "",
          facility: pickerItem?.facility || "",
          district: pickerItem?.district || "",
          maxPosts:
            pickerItem?.vacant ||
            this.getExt(pos, EXT.MAX_PRACTITIONERS, "valueInteger") ||
            0,
          posDescription:
            this.getExt(pos, EXT.ADV_DESCRIPTION, "valueString") || "",
          minimumRequirements:
            this.getExt(pos, EXT.MINIMUM_REQUIREMENTS, "valueString") || "",
          additionalRequirements:
            this.getExt(pos, EXT.ADDITIONAL_REQUIREMENTS, "valueString") || "",
        };

        // ── Designation name (reference → Basic → ihris-basic-name) ──
        const desigRef = this.getExt(pos, EXT.DESIGNATION, "valueReference");
        if (desigRef?.reference) {
          try {
            const dId = desigRef.reference.split("/")[1];
            const dRes = await fetch(`/fhir/Basic/${dId}`);
            const d = await dRes.json();
            details.designation =
              this.getExt(d, EXT.POS_NAME, "valueString") ||
              details.designation;
          } catch (err) {
            console.log(err);
          }
        }

        // ── Salary grade name (reference → Basic → ihris-basic-name) ─
        const gradeRef = this.getExt(pos, EXT.GRADE, "valueReference");
        if (gradeRef?.reference) {
          try {
            const gId = gradeRef.reference.split("/")[1];
            const gRes = await fetch(`/fhir/Basic/${gId}`);
            const g = await gRes.json();
            details.grade =
              this.getExt(g, EXT.POS_NAME, "valueString") || details.grade;
          } catch (err) {
            console.log(err);
          }
        }

        // ── Department label (valueCoding on the position) ────────────
        const deptCoding = this.getExt(pos, EXT.DEPARTMENT, "valueCoding");
        if (deptCoding && !details.department) {
          details.department = deptCoding.display || deptCoding.code || "";
        }

        // ── Facility name + district chain ────────────────────────────
        // Position → facility Location → partOf council Location → partOf district Location
        const facRef = this.getExt(pos, EXT.FACILITY, "valueReference");
        if (facRef?.reference) {
          try {
            const fRes = await fetch(`/fhir/${facRef.reference}`);
            const fData = await fRes.json();
            details.facility = fData.name || details.facility;

            // council
            if (fData.partOf?.reference) {
              const cRes = await fetch(`/fhir/${fData.partOf.reference}`);
              const cData = await cRes.json();
              // district
              if (cData.partOf?.reference) {
                const distRes = await fetch(`/fhir/${cData.partOf.reference}`);
                const distData = await distRes.json();
                details.district = distData.name || details.district;
              }
            }
          } catch (err) {
            console.log(err);
          }
        }

        this.positionDetails = details;
        this.positionResource = pos;

        // Sync back to form for display in the trigger
        this.form.position.facility = details.facility;
        this.form.position.department = details.department;

        // Cap maximumPractitioners at actual vacancies
        if (
          this.form.maximumPractitioners &&
          details.maxPosts > 0 &&
          +this.form.maximumPractitioners > details.maxPosts
        ) {
          this.form.maximumPractitioners = details.maxPosts;
        }
      } catch (err) {
        console.error("enrichPositionDetails error", err);
      }
    },

    // ── Date handling ──────────────────────────────────────────────────
    onStartDateChange() {
      // If the existing end date would now violate the 30-day minimum, clear it
      if (
        this.form.endDate &&
        this.minEndDate &&
        this.form.endDate < this.minEndDate
      ) {
        this.form.endDate = null;
      }
    },

    // ── Extend deadline ────────────────────────────────────────────────
    openExtendDialog() {
      if (this.hiringClosed) return;
      this.extendDate = null;
      this.extendError = "";
      this.extendDialog = true;
    },

    async applyExtension() {
      this.extendError = "";
      if (!this.extendDate) {
        this.extendError = "Please select a new closing date.";
        return;
      }
      if (this.extendDate <= this.form.endDate) {
        this.extendError =
          "New closing date must be later than the current closing date.";
        return;
      }
      this.form.endDate = this.extendDate;
      this.extendDialog = false;
      this.afterSaveMessage = "Deadline extended successfully";
      await this.submit();
    },

    // ── Submit ─────────────────────────────────────────────────────────
    async submit() {
      if (this.hiringClosed) return;
      this.formSubmitted = true;
      const valid = this.$refs.form.validate();
      if (!valid || !this.form.position.reference) return;

      this.saving = true;
      try {
        this.fhir = {
          name: this.form.name,
          description: this.form.description || "",
          position: this.form.position.reference,
          startDate: this.form.startDate,
          endDate: this.form.endDate,
          maximumPractitioners: +this.form.maximumPractitioners,
          employmentCategory: this.form.employmentCategory,
          employmentEnd: this.showEmploymentEnd ? this.form.employmentEnd : null,
        };

        if (!this.afterSaveMessage) {
          this.afterSaveMessage = this.isEdit
            ? "Advertisement updated successfully"
            : "Advertisement published successfully";
        }

        await this.processFHIR();
        this.fhirId = "";
        // Navigate back to the recruitment landing page
        this.goToLanding();
      } catch (err) {
        console.error("submit error", err);
      } finally {
        this.saving = false;
      }
    },

    // ── Filter treeview ────────────────────────────────────────────────
    async loadFilterTree() {
      if (this.filterTree.items.length) return;
      this.filterTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [],
        }));
        nodes.forEach((n) => {
          this.filterTree.treeLookup[n.id] = { name: n.name, type: "district" };
        });
        this.filterTree.items = nodes;
      } catch (err) {
        console.error("loadFilterTree error", err);
      } finally {
        this.filterTree.loading = false;
      }
    },

    fetchFilterChildren(item) {
      const parentInfo = this.filterTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = [];
            this.filterTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchFilterChildren error", err));
    },

    clearFilterTree() {
      this.filterTree.active = [];
      this.filterTree.displayValue = "";
    },

    // ── Helpers ────────────────────────────────────────────────────────
    getExt(resource, url, type) {
      const ext = resource?.extension?.find((e) => e.url === url);
      return ext ? ext[type] : null;
    },

    formatDate(d) {
      if (!d) return "—";
      return new Date(d).toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },
  },
};
</script>

